//! Whether the allocator shim's captures could see the growth the process itself measured.
//!
//! The shim writes its record at process exit, after `exit()` freed the calling thread's
//! thread-locals and the static destructors' state, so a record taken there misses what such a
//! holder keeps. A driver generated by DLA hands the shim a snapshot while the state is alive;
//! a record taken at exit is checked against the process's own last checkpoint, which
//! `dla harness run` keeps with it (`driver`: x, live bytes, live blocks).
//!
//! The comparison is of growth over the ordered captures, never of totals: the exit record is
//! normally somewhat below the in-process reading (the driver counts allocator-level bytes the
//! shim does not). A capture series is **blind** when both hold:
//!
//! - the driver's live bytes rose by more than [`FLOOR_BYTES`] and [`FLOOR_PERCENT`] of the first
//!   capture's reading, between the first and the last capture that carry a driver reading;
//! - the shim's live total rose by less than half of that rise.
//!
//! The shim's `native.peak_bytes` rising while its live total stays flat is a hint printed next to
//! the verdict, never a trigger: a transient buffer gives the same shape.

use dla_core::HarnessDump;
use serde_json::{Value, json};

/// The rise of the driver's live bytes below which a flat capture is not doubted.
pub const FLOOR_BYTES: u64 = 64 << 10;
/// The share of the first capture's driver reading the rise must also exceed, in percent.
pub const FLOOR_PERCENT: u64 = 10;

/// What one capture says, for the comparison.
#[derive(Debug, Clone, Default)]
pub struct Reading {
    /// The shim's live bytes at the capture (`native.live_bytes`, else the sum of its stacks).
    pub shim_live: u64,
    /// The shim's peak of live bytes, when the record has it.
    pub shim_peak: Option<u64>,
    /// `"exit"`, `"snapshot"` or `"signal"`; `None` for a record of an older shim.
    pub at: Option<String>,
    /// The driver's `(x, live bytes)` of the same process, when the record carries them.
    pub driver: Option<(u64, u64)>,
}

impl Reading {
    /// The reading of one shim record; `stack_total` is the sum of its stacks' live bytes.
    pub fn of(d: &HarnessDump, stack_total: u64) -> Self {
        let value = |k: &str| {
            d.values
                .as_ref()
                .and_then(|v| v.get(k))
                .copied()
                .flatten()
                .filter(|v| *v >= 0.0)
                .map(|v| v as u64)
        };
        Self {
            shim_live: value("native.live_bytes").unwrap_or(stack_total),
            shim_peak: value("native.peak_bytes"),
            at: d.at.clone(),
            driver: d.driver.as_ref().map(|d| (d.x, d.live_bytes)),
        }
    }
}

/// The verdict of [`check`].
#[derive(Debug, Clone, PartialEq)]
pub enum Check {
    /// Not enough to compare, and the exit view may miss state freed at exit: no capture carries
    /// a driver reading and not every one is a snapshot (a command-mode capture of the
    /// project's own process). A hint on the peak is attached when the peak rose with a flat
    /// live total.
    Unchecked {
        /// The shim's peak rose across the captures while its live total stayed flat.
        peak_hint: bool,
    },
    /// Compared: the shim's captures hold the growth the driver measured (or the driver's did
    /// not rise above the floor).
    Clear,
    /// The shim's captures did not hold the growth the driver measured.
    Blind(Blind),
}

/// The numbers of a blind series.
#[derive(Debug, Clone, PartialEq)]
pub struct Blind {
    /// The driver's live bytes at each capture that had a reading, in capture order.
    pub driver: Vec<u64>,
    /// The shim's live bytes at the same captures.
    pub shim: Vec<u64>,
    /// The x of the first and the last of those captures.
    pub x: (u64, u64),
    /// The shim's peak rose while its live total did not (a hint, not a cause).
    pub peak_hint: bool,
    /// The last capture was a snapshot: the state is held outside the shim's view.
    pub snapshot: bool,
}

fn mb(b: u64) -> String {
    format!("{:.2} MB", b as f64 / 1e6)
}

fn series(v: &[u64]) -> String {
    v.iter().map(|b| mb(*b)).collect::<Vec<_>>().join(" -> ")
}

impl Blind {
    /// One line with both series of numbers and what the capture cannot do.
    pub fn sentence(&self) -> String {
        format!(
            "the capture is blind: the process's own live bytes rose {} (x {} to {}) while the shim's total rose {}{}; it cannot clear or explain growth the process measured",
            series(&self.driver),
            self.x.0,
            self.x.1,
            series(&self.shim),
            if self.peak_hint {
                ", and its peak rose while its live total did not (state that was alive and was freed before the record)"
            } else {
                ""
            },
        )
    }

    /// What to do next. Without a snapshot: take it. With one that is still blind: the state is
    /// held where the shim does not look.
    pub fn needed(&self) -> String {
        if self.snapshot {
            "the capture was taken as a snapshot, while the state was alive, and is still blind: the state is held outside the shim's view (memory a custom or statically linked allocator, an mmap or a runtime's own arena serves); decide the growth with `dla alloc-test <H> --finding <F>`, which reads the process's own series, or capture the project's own program in command mode".to_owned()
        } else {
            "take the capture while the state is alive: the Rust and C drivers `dla harness gen` writes call the shim's snapshot after their last unit (a harness generated before that needs `dla harness gen` again, then `dla harness run <H> --mode fresh --capture alloc`); a program of the project calls dla_shim_snapshot(x) before it returns, or keeps the state in a static; or decide the growth with `dla alloc-test <H> --finding <F>`".to_owned()
        }
    }

    /// The numbers as the record states them.
    pub fn numbers(&self) -> Value {
        json!({
            "driver_live_bytes": self.driver,
            "shim_live_bytes": self.shim,
            "x": [self.x.0, self.x.1],
            "peak_hint": self.peak_hint,
            "snapshot": self.snapshot,
        })
    }
}

/// Compares the ordered captures `r` (by x). See the module text for the rule.
pub fn check(r: &[Reading]) -> Check {
    let peak_hint = {
        let (first, last) = (r.first(), r.last());
        match (
            first.and_then(|f| f.shim_peak),
            last.and_then(|l| l.shim_peak),
        ) {
            (Some(p0), Some(p1)) if r.len() >= 2 => {
                let live0 = first.map_or(0, |f| f.shim_live);
                let live1 = last.map_or(0, |l| l.shim_live);
                p1 > p0 && p1 - p0 >= FLOOR_BYTES && live1.saturating_sub(live0) < (p1 - p0) / 2
            }
            _ => false,
        }
    };
    let with: Vec<(&Reading, (u64, u64))> =
        r.iter().filter_map(|c| c.driver.map(|d| (c, d))).collect();
    let Some(((first, (x0, d0)), (last, (x1, d1)))) =
        with.first().zip(with.last()).map(|(a, b)| (*a, *b))
    else {
        let all_snapshots = !r.is_empty() && r.iter().all(|c| c.at.as_deref() == Some("snapshot"));
        return if all_snapshots {
            Check::Clear
        } else {
            Check::Unchecked { peak_hint }
        };
    };
    if with.len() < 2 || x1 <= x0 {
        return Check::Unchecked { peak_hint };
    }
    let rise = d1.saturating_sub(d0);
    let floor = FLOOR_BYTES.max(d0 / 100 * FLOOR_PERCENT);
    if rise <= floor {
        return Check::Clear;
    }
    let shim_rise = last.shim_live.saturating_sub(first.shim_live);
    if u128::from(shim_rise) * 2 >= u128::from(rise) {
        return Check::Clear;
    }
    Check::Blind(Blind {
        driver: with.iter().map(|(_, (_, d))| *d).collect(),
        shim: with.iter().map(|(c, _)| c.shim_live).collect(),
        x: (x0, x1),
        peak_hint,
        snapshot: last.at.as_deref() == Some("snapshot"),
    })
}

/// The limitation for captures that were not compared with the process's own readings.
pub const UNCHECKED: &str = "these captures carry no checkpoint of the same process (a capture of the project's own process in command mode), so they were not compared with what the process measured: the exit view may miss state freed at exit (a thread-local or a static destructor's)";

/// The hint on a peak that rose while the live total stayed flat, for captures not compared.
pub const PEAK_HINT: &str = "hint: the shim's peak of live bytes rose across the captures while its live total did not: state that was alive may have been freed before the exit record (a transient buffer gives the same shape)";

#[cfg(test)]
mod tests {
    use super::*;

    fn r(shim: u64, peak: u64, driver: Option<(u64, u64)>, at: &str) -> Reading {
        Reading {
            shim_live: shim,
            shim_peak: Some(peak),
            at: Some(at.to_owned()),
            driver,
        }
    }

    #[test]
    fn driver_rising_and_shim_flat_is_blind_with_both_series() {
        let c = [
            r(2_510_682, 2_681_625, Some((440, 2_678_905)), "exit"),
            r(2_510_682, 3_541_785, Some((880, 3_539_065)), "exit"),
            r(2_510_682, 4_524_825, Some((1760, 4_522_105)), "exit"),
            r(2_510_682, 6_491_081, Some((3520, 6_488_185)), "exit"),
        ];
        let Check::Blind(b) = check(&c) else {
            panic!("{:?}", check(&c))
        };
        assert_eq!(b.driver.len(), 4);
        assert_eq!(b.shim, vec![2_510_682; 4]);
        assert!(b.peak_hint && !b.snapshot);
        let s = b.sentence();
        assert!(
            s.contains("2.68 MB") && s.contains("6.49 MB") && s.contains("2.51 MB"),
            "{s}"
        );
        assert!(!b.needed().contains("more work"));
        assert!(b.needed().contains("snapshot"));
    }

    #[test]
    fn a_snapshot_that_is_still_blind_says_the_state_is_outside_the_shims_view() {
        let c = [
            r(1_000_000, 1_000_000, Some((100, 1_000_000)), "snapshot"),
            r(1_000_000, 1_000_000, Some((200, 3_000_000)), "snapshot"),
        ];
        let Check::Blind(b) = check(&c) else { panic!() };
        assert!(b.snapshot);
        assert!(
            b.needed().contains("outside the shim's view"),
            "{}",
            b.needed()
        );
    }

    #[test]
    fn both_rising_is_clear() {
        let c = [
            r(1_000_000, 1_000_000, Some((100, 1_100_000)), "exit"),
            r(3_000_000, 3_000_000, Some((200, 3_100_000)), "exit"),
        ];
        assert_eq!(check(&c), Check::Clear);
    }

    #[test]
    fn a_transient_peak_with_live_flat_in_both_is_not_blind() {
        let c = [
            r(1_000_000, 1_000_000, Some((100, 1_040_000)), "exit"),
            r(1_000_000, 9_000_000, Some((200, 1_040_000)), "exit"),
        ];
        assert_eq!(check(&c), Check::Clear);
    }

    #[test]
    fn no_checkpoint_is_unchecked_and_a_peak_only_gives_the_hint() {
        let c = [
            r(1_000_000, 1_000_000, None, "exit"),
            r(1_000_000, 5_000_000, None, "exit"),
        ];
        assert_eq!(check(&c), Check::Unchecked { peak_hint: true });
        let flat = [
            r(1_000_000, 1_000_000, None, "exit"),
            r(1_000_000, 1_000_000, None, "exit"),
        ];
        assert_eq!(check(&flat), Check::Unchecked { peak_hint: false });
    }

    #[test]
    fn a_rise_under_the_floor_is_not_doubted() {
        let c = [
            r(100_000, 100_000, Some((100, 100_000)), "exit"),
            r(100_000, 100_000, Some((200, 150_000)), "exit"),
        ];
        assert_eq!(check(&c), Check::Clear);
    }
}
